      {args:[{visibles:[{id:1,texto:'A'}],espera:[]},{tipo:'agregar',aviso:{id:2,texto:'B'}},1],expected:{visibles:[{id:1,texto:'A'}],espera:[{id:2,texto:'B'}]},preserveInput:true},
      {args:[{visibles:[{id:1,texto:'A'}],espera:[{id:2,texto:'B'},{id:3,texto:'C'}]},{tipo:'cerrar',id:1},1],expected:{visibles:[{id:2,texto:'B'}],espera:[{id:3,texto:'C'}]},preserveInput:true},
      {args:[{visibles:[{id:1,texto:'A'}],espera:[{id:2,texto:'B'}]},{tipo:'agregar',aviso:{id:2,texto:'Otro'}},1],expected:{visibles:[{id:1,texto:'A'}],espera:[{id:2,texto:'B'}]}},
      {args:[{visibles:[{id:1,texto:'A'}],espera:[{id:2,texto:'B'}]},{tipo:'cerrar',id:2},1],expected:{visibles:[{id:1,texto:'A'}],espera:[]}},
      {args:[{visibles:[{id:1,texto:'A'}],espera:[]},{tipo:'cerrar',id:9},1],expected:{visibles:[{id:1,texto:'A'}],espera:[]}}
